window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a8740130688c1863"]={"versions": [{"id": "FIG-a8740130688c1863", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (<code>class HM_AliveSupervision</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform – Platform Health Management (PHM / Health Monitoring), Sub-Feature <em>Alive Supervision</em>.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Konfigurationsstruktur zur frequenzbasierten Lebendigkeitsüberwachung zyklischer Programmabläufe in Adaptive Applications.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AliveSupervision</code> (Klasse / Konfigurationsentität):</strong> Definiert das Überwachungsfenster und die Toleranzkriterien für einen spezifischen Prüfpunkt.\n<ul class=\"fig-list\"><li><code>- AliveReferenceCycle</code>: Dauer bzw. Zyklusanzahl des Referenzbeobachtungsintervalls, über das die Checkpoint-Ereignisse akkumuliert und ausgewertet werden.\n</li><li><code>- ExpectedAliveIndications</code>: Sollwert der erwarteten Checkpoint-Meldungen innerhalb eines <code>AliveReferenceCycle</code>.\n</li><li><code>- MinMargin</code>: Untere zulässige Toleranzgrenze (negative Abweichung von <code>ExpectedAliveIndications</code>).\n</li><li><code>- MaxMargin</code>: Obere zulässige Toleranzgrenze (positive Abweichung von <code>ExpectedAliveIndications</code>).\n</li></ul>\n</li><li><strong><code>Checkpoint</code> (Klasse / Entität):</strong> Repräsentiert einen eindeutig identifizierbaren, im Code instrumentierten Ausführungspunkt innerhalb einer überwachten Entität (<code>SupervisedEntity</code>).\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>SupervisedCheckpoint</code> von <code>AliveSupervision</code> nach <code>Checkpoint</code> mit Kardinalität <code>1</code>. Eine <code>AliveSupervision</code>-Instanz ist zwingend und exklusiv genau einem <code>Checkpoint</code> zugeordnet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger &amp; Zählung:</strong>\n<ul class=\"fig-list\"><li>Die überwachte Applikation meldet die Ausführung synchron über die funktionale C++ API (z. B. <code>ara::phm::SupervisedEntity::ReportCheckpoint()</code>).\n</li><li>Der PHM-Dienst inkrementiert den internen Zähler für die referenzierte <code>Checkpoint</code>-Instanz während der Periode <code>AliveReferenceCycle</code>.\n</li></ul>\n</li><li><strong>Evaluierungslogik &amp; Statuswechsel:</strong>\n<ul class=\"fig-list\"><li>Am Ende jedes <code>AliveReferenceCycle</code> prüft der PHM-Algorithmus, ob die Anzahl empfangener Meldungen N innerhalb des Akzeptanzfensters liegt:\n $$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le N \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$\n</li><li><strong>Gutfall:</strong> Alive-Zustand bleibt bzw. wechselt nach <code>ALIVE_OK</code>.\n</li><li><strong>Fehlerfall:</strong> Bei N &lt; Min (Starvation/Deadlock/Crash) oder N &gt; Max (Babbling Idiot/Endlosschleife) wechselt der Status nach <code>ALIVE_FAILED</code> bzw. nach konfigurierten Fehlzyklen nach <code>ALIVE_EXPIRED</code>.\n</li></ul>\n</li><li><strong>Folgeaktionen:</strong>\n<ul class=\"fig-list\"><li>Der Alive-Status fließt in die globale State-Machine des PHM ein; bei Verletzung triggert PHM Recovery Actions über das <em>Execution Management</em> / <em>State Management</em> (z. B. Prozess-Neustart, Degradierung in Safe State) oder meldet an das Diagnose-Subsystem.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfiguration (Deployment / ARXML):</strong>\n<ul class=\"fig-list\"><li><code>AliveReferenceCycle</code> muss exakt auf die Task-Aktivierungsrate des OS (POSIX/Linux/QNX) abgestimmt werden.\n</li><li><code>MinMargin</code> und <code>MaxMargin</code> müssen Task-Jitter, Scheduling-Latenzen und transiente Lastspitzen abbilden; zu enge Margins führen zu False-Positives im Health-Monitor.\n</li></ul>\n</li><li><strong>Implementierungsvertrag (Applikations-Entwickler):</strong>\n<ul class=\"fig-list\"><li>Checkpoints für <code>AliveSupervision</code> dürfen ausschließlich in streng deterministischen, periodischen Kontrollflüssen aufgerufen werden (z. B. zyklische <code>Execute()</code>-Routinen).\n</li><li>Der Aufruf von <code>ReportCheckpoint()</code> innerhalb asynchroner Event-Callbacks oder bedingter Verzweigungen ist unzulässig, da dies zu unberechenbaren Indikationszahlen führt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cdda228d867d4127", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (<code>class HM_AliveSupervision</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform – Platform Health Management (PHM / Health Monitoring), Sub-Feature <em>Alive Supervision</em>.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Konfigurationsstruktur zur frequenzbasierten Lebendigkeitsüberwachung zyklischer Programmabläufe in Adaptive Applications.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AliveSupervision</code> (Klasse / Konfigurationsentität):</strong> Definiert das Überwachungsfenster und die Toleranzkriterien für einen spezifischen Prüfpunkt.\n<ul class=\"fig-list\"><li><code>- AliveReferenceCycle</code>: Dauer bzw. Zyklusanzahl des Referenzbeobachtungsintervalls, über das die Checkpoint-Ereignisse akkumuliert und ausgewertet werden.\n</li><li><code>- ExpectedAliveIndications</code>: Sollwert der erwarteten Checkpoint-Meldungen innerhalb eines <code>AliveReferenceCycle</code>.\n</li><li><code>- FailedReferenceCyclesTolerance</code>: Anzahl tolerierter aufeinanderfolgender Evaluierungszyklen mit verletzter Alive-Bedingung (<code>ALIVE_FAILED</code>), bevor der Zustand endgültig nach <code>ALIVE_EXPIRED</code> wechselt.\n</li><li><code>- MaxMargin</code>: Obere zulässige Toleranzgrenze (positive Abweichung von <code>ExpectedAliveIndications</code>).\n</li><li><code>- MinMargin</code>: Untere zulässige Toleranzgrenze (negative Abweichung von <code>ExpectedAliveIndications</code>).\n</li></ul>\n</li><li><strong><code>Checkpoint</code> (Klasse / Entität):</strong> Repräsentiert einen eindeutig identifizierbaren, im Code instrumentierten Ausführungspunkt innerhalb einer überwachten Entität (<code>SupervisedEntity</code>).\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Gerichtete Assoziation <code>SupervisedCheckpoint</code> von <code>AliveSupervision</code> nach <code>Checkpoint</code> mit Kardinalität <code>1</code>. Eine <code>AliveSupervision</code>-Instanz ist zwingend und exklusiv genau einem <code>Checkpoint</code> zugeordnet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger &amp; Zählung:</strong>\n<ul class=\"fig-list\"><li>Die überwachte Applikation meldet die Ausführung synchron über die funktionale C++ API (z. B. <code>ara::phm::SupervisedEntity::ReportCheckpoint()</code>).\n</li><li>Der PHM-Dienst inkrementiert den internen Zähler für die referenzierte <code>Checkpoint</code>-Instanz während der Periode <code>AliveReferenceCycle</code>.\n</li></ul>\n</li><li><strong>Evaluierungslogik &amp; Statuswechsel:</strong>\n<ul class=\"fig-list\"><li>Am Ende jedes <code>AliveReferenceCycle</code> prüft der PHM-Algorithmus, ob die Anzahl empfangener Meldungen N innerhalb des Akzeptanzfensters liegt:\n $$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le N \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$\n</li><li><strong>Gutfall:</strong> Alive-Zustand bleibt bzw. wechselt nach <code>ALIVE_OK</code>.\n</li><li><strong>Fehlerfall:</strong> Bei N &lt; Min (Starvation/Deadlock/Crash) oder N &gt; Max (Babbling Idiot/Endlosschleife) wechselt der Status nach <code>ALIVE_FAILED</code> bzw. nach konfigurierten Fehlzyklen nach <code>ALIVE_EXPIRED</code>.\n</li></ul>\n</li><li><strong>Folgeaktionen:</strong>\n<ul class=\"fig-list\"><li>Der Alive-Status fließt in die globale State-Machine des PHM ein; bei Verletzung triggert PHM Recovery Actions über das <em>Execution Management</em> / <em>State Management</em> (z. B. Prozess-Neustart, Degradierung in Safe State) oder meldet an das Diagnose-Subsystem.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfiguration (Deployment / ARXML):</strong>\n<ul class=\"fig-list\"><li><code>AliveReferenceCycle</code> muss exakt auf die Task-Aktivierungsrate des OS (POSIX/Linux/QNX) abgestimmt werden.\n</li><li><code>MinMargin</code> und <code>MaxMargin</code> müssen Task-Jitter, Scheduling-Latenzen und transiente Lastspitzen abbilden; zu enge Margins führen zu False-Positives im Health-Monitor.\n</li></ul>\n</li><li><strong>Implementierungsvertrag (Applikations-Entwickler):</strong>\n<ul class=\"fig-list\"><li>Checkpoints für <code>AliveSupervision</code> dürfen ausschließlich in streng deterministischen, periodischen Kontrollflüssen aufgerufen werden (z. B. zyklische <code>Execute()</code>-Routinen).\n</li><li>Der Aufruf von <code>ReportCheckpoint()</code> innerhalb asynchroner Event-Callbacks oder bedingter Verzweigungen ist unzulässig, da dies zu unberechenbaren Indikationszahlen führt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a8740130688c1863", "to": "FIG-cdda228d867d4127", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>AliveSupervision</code>: Attribut <code>- FailedReferenceCyclesTolerance</code> neu hinzugefügt.\n</li></ul>"}]};
